        self.board = [" "] * 9
        self.current = "X"

    def display(self):
        b = self.board
        print()
        for r in range(3):
            print("  %s | %s | %s " % (b[3 * r], b[3 * r + 1], b[3 * r + 2]))
            if r < 2:
                print(" ---+---+---")
        print()

    def winner(self):
        for a, b, c in self.WIN_LINES:
            if self.board[a] != " " and self.board[a] == self.board[b] == self.board[c]:
                return self.board[a]
        return None

    def full(self):
        return " " not in self.board

    def move(self, pos):
        if 1 <= pos <= 9 and self.board[pos - 1] == " ":
            self.board[pos - 1] = self.current
            return True
        return False

    def switch(self):
        self.current = "O" if self.current == "X" else "X"

    def play_round(self):
        self.board = [" "] * 9
        self.current = "X"
        print("Positions are numbered 1-9 (top-left to bottom-right).")
